// Made by tools/make_format_info.py from MegaconvertGS's Info on format texts; don't edit.

/// The Info on format text of each load and save format, by its id.
public enum FormatInfo {
    public static let load: [String: String] = [
        "hgrbw": "HiRes black & white: the Apple II high resolution screen (8192 bytes, usually a BIN or FOT file) as a monochrome monitor shows it, each of its 280 x 192 dots white or black.\nLoaded as 280 x 192 in 320 mode.",
        "hgr": "HiRes color: the Apple II high resolution screen, 8192 bytes: 280 x 192 dots in black, white, violet, green, blue and orange, worked out from the dots and their neighbors as on a color monitor.\nLoaded as 280 x 192 in 320 mode. Also packed (PackBytes: $08, $4000; LZ4FH: $08, $8066); a $08 file with byte 120 set to black & white or Double HiRes opens so.",
        "dhrbw": "Double HiRes black & white: the Apple II double high resolution screen (16384 bytes, the auxiliary half first) as a monochrome monitor shows it, each of its 560 x 192 dots white or black.\nLoaded as 560 x 192 in 640 mode. Also NAME.BIN with NAME.AUX, and bmp2dhr’s .DHM masks.",
        "dhr": "Double HiRes color: the double high resolution screen of the Apple IIe, IIc and IIgs, 16384 bytes, the auxiliary memory half first: 140 x 192 pixels in 16 colors, each pixel made of 4 dots.\nLoaded in 320 mode, each pixel doubled across: 280 x 192. Also read packed with PackBytes ($08, $4001), as two files (NAME.BIN, main, and NAME.AUX) and as bmp2dhr pieces (.DHR).",
        "psbw": "Print Shop graphic: a graphic from Broderbund’s original Print Shop for the Apple II, 88 x 52 dots in black and white, 572 bytes. Print Shop keeps them on DOS 3.3 disks, so copy them to ProDOS first.\nLoaded as 88 x 52 in 320 mode.",
        "tscan": "ThunderScan raw scan: a scan from Thunderware’s ThunderScan, the scanner that takes the place of the ribbon in an ImageWriter printer: a 256-byte header, then rows of 4-bit gray samples.\nIt becomes a gray true color picture, which the Remap dialog then turns into a screen image.",
        "woa": "Works of Art: black and white clip art from Springboard Publishing’s Works of Art collections.\nEach page chosen becomes a monochrome image.",
        "tdm40": "TDM 40-column text screen: the Apple II text screen memory saved as a BIN file, as On Three’s The Desktop Manager (TDM) captures it: 1024 bytes, 40 columns by 24 lines.\nDrawn with the Apple II characters, normal and inverse, as 280 x 192 in 320 mode.",
        "tdm80": "TDM 80-column text screen: the Apple II 80-column text screen memory saved as a BIN file, as TDM (The Desktop Manager) captures it: 2048 bytes, the auxiliary memory half first.\nDrawn with the Apple II characters, normal and inverse, as 560 x 192 in 640 mode.",
        "lores": "LoRes: the Apple II low resolution screen, 1024 bytes (the text page, usually a BIN file): 40 x 48 blocks in 16 colors.\nLoaded as 280 x 192 in 320 mode, each block 7 x 4 pixels.",
        "dlores": "Double LoRes: the 80-column low resolution screen of the Apple IIe, IIc and IIgs, 2048 bytes, the auxiliary memory half first: 80 x 48 blocks in 16 colors.\nLoaded as 280 x 192 in 320 mode, each block 3 or 4 pixels across and 4 down.",
        "shr": "SuperHiRes ($C0 PNT, $C1 PIC): reads the common Super Hi-Res files and works out by itself which kind each one is: ProDOS type $C0 with aux type $0000 (PaintWorks), $0001 (PackBytes) or $0002 (Apple Preferred), or type $C1 with aux type $0000 (a plain screen).\nLoaded as it is, at its whole size; an Apple Preferred picture with 3200 colors keeps a color table for every line.",
        "c1": "$C1 screen: the Super Hi-Res screen saved byte for byte, 32768 bytes: the pixels, the 200 SCBs (each line’s mode and color table) and 16 color tables. ProDOS type $C1 (PIC), aux type $0000, though early pictures were often BIN files.\nLoaded unchanged. Any file of at least 32000 bytes can be read this way.",
        "drm": "DreamGrafix: pictures from the DreamGrafix paint program, ProDOS type $C0 (PNT), aux type $8005, LZW compressed. This is the 256 color kind, a screen using all 16 color tables.\nUnpacked and loaded unchanged, in 320 or 640 mode, whichever most of its lines use.",
        "drm3200": "DreamGrafix \"3200 color\": the DreamGrafix kind with its own palette on each of the 200 lines, ProDOS type $C0 (PNT), aux type $8005, LZW compressed.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image. Remap’s multipalette mode keeps more of its colors.",
        "pwgold": "PaintWorks Gold 640 mode: PaintWorks Gold saves 640 mode pictures with 320 mode headers, in all of its formats, so other programs show them at half width in the wrong colors.\nThis reads them as the 640 x 200 pictures they are. Save them again, as Apple Preferred for example.",
        "psgs": "Print Shop IIgs color graphic: a graphic from Broderbund’s Print Shop IIgs, 88 x 52 dots in 8 colors (black, white, red, orange, yellow, green, blue and purple) made of yellow, magenta and cyan planes, 1716 bytes.\nLoaded as 88 x 52 in 320 mode with the standard colors.",
        "cgt": "Print Shop IIgs built-in graphics: the libraries GRAPHIC.CGT0 to GRAPHIC.CGT7 that come with Print Shop IIgs, each a series of 88 x 52 color graphics followed by their names.\nThe first graphic in the file is loaded, as 88 x 52 in 320 mode.",
        "icon": "Finder icon file: the IIgs Finder’s icons, ProDOS type $CA (ICN). Each entry says which files it is for and holds a large and a small icon, each with a mask, in up to 16 colors.\nThe first entry’s large icon is shown in 640 mode with the standard colors, on white.",
        "ast": "AST picture data: a full color picture from VisionEffects, the software of AST’s VisionPlus video digitizer, saved as picture data from 320 mode: red, green and blue planes of 4-bit samples, 96000 bytes.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "ceyes": "ComputerEyes GS raw data: a full color capture from the ComputerEyes GS video digitizer: red, green and blue planes of 6-bit samples, stored column by column, about 192000 bytes.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "3200": "\"3200 color\" picture: 320 mode pixels followed by a color table for each of the 200 lines, 38400 bytes, ProDOS type $C1 (PIC), aux type $0002, called Brooks format after John Brooks. Special viewers show them, changing the palette on every line.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "3200c": "\"3200 color\" picture, compressed: two packed kinds are read: .3201 files (an APP header, the 200 color tables, then the pixels packed with PackBytes) and a run coded kind with a 7-byte header.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "degas": "Degas (.PI1, .PI2, .PI3): Atari ST pictures from Degas and Degas Elite, 32034 bytes. Low resolution (320 x 200, 16 colors) loads in 320 mode, medium (640 x 200, 4 colors) in 640 mode, with their own colors.\nHigh resolution (640 x 400, black & white) becomes a monochrome image.",
        "degaselite": "Degas Elite (.PC1, .PC2, .PC3): the compressed Atari ST pictures of Degas Elite. Low resolution (320 x 200, 16 colors) loads in 320 mode, medium (640 x 200, 4 colors) in 640 mode, with their own colors.\nHigh resolution (640 x 400, black & white) becomes a monochrome image.",
        "neo": "Neochrome (.NEO): Atari ST pictures from the Neochrome paint program, 32128 bytes, nearly always low resolution: 320 x 200 in 16 colors, loaded in 320 mode with their own colors.\nMedium and high resolution ones are read as Degas pictures are.",
        "tiny": "Tiny (.TNY, .TN1 to .TN3): compressed Atari ST pictures. Low resolution (320 x 200, 16 colors) loads in 320 mode, medium (640 x 200, 4 colors) in 640 mode, with their own colors.\nHigh resolution (640 x 400, black & white) becomes a monochrome image.",
        "spu": "Spectrum 512 (.SPU): Atari ST pictures from Spectrum 512, which changes palettes three times along each line to show up to 512 colors: 51104 bytes, the top line always black.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "spc": "Spectrum 512 compressed (.SPC): Spectrum 512 pictures with the bit planes and each line’s palettes packed: 320 x 200 with up to 512 colors, the top line black.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "iff": "IFF: the Amiga’s standard picture file (FORM ILBM), also used by DeluxePaint on the PC (FORM PBM, .LBM): 1 to 8 bit planes, Extra HalfBrite, HAM and 24-bit, packed or not, found anywhere in the file.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "doodle": "Doodle: Commodore 64 pictures from the Doodle paint program, whose file names usually start with DD: 320 x 200 dots, with two colors in each 8 x 8 cell.\nLoaded as 320 x 200 in 320 mode with the Commodore 64 colors.",
        "koala": "Koala: Commodore 64 multicolor pictures from the KoalaPad’s paint program (.KOA, .KLA), 10003 bytes: 160 x 200 double-wide pixels, with four colors in each 4 x 8 cell.\nLoaded as 320 x 200 in 320 mode with the Commodore 64 colors.",
        "c64ps": "C64 Print Shop screen: a Commodore 64 Print Shop screen, a load address and then a 320 x 200 bitmap (8000 bytes) in black and white.\nLoaded as 320 x 200 in 320 mode, white on black. Other C64 bitmaps can be viewed this way too, without their colors.",
        "artst": "Art Studio (OCP): hires pictures from the Commodore 64’s Art Studio, 9009 bytes: 320 x 200 dots, a color pair for each 8 x 8 cell; and the same pictures of 9002 bytes (Interpaint, Gigapaint and others).\nIt becomes a screen image in the C64’s 16 colors.",
        "aas": "Advanced Art Studio (OCP): multicolor pictures from the Commodore 64’s Advanced Art Studio, 10018 bytes: 160 x 200 wide dots in four colors for each cell.\nIt becomes a screen image in the C64’s 16 colors.",
        "fli": "FLI Graph (.FLI): Commodore 64 multicolor pictures with new screen colors on every line, 17409 bytes.\nIt becomes a screen image in the C64’s 16 colors; the first three columns, which the C64 can’t show, are black.",
        "amica": "Amica Paint (.AMI): packed Commodore 64 multicolor pictures, as Koala pictures.\nIt becomes a screen image in the C64’s 16 colors.",
        "mpnt640": "MacPaint as 640 mode grays: MacPaint documents (Mac file type PNTG) are 576 x 720 dots, black and white, packed with PackBits. A MacBinary header is skipped.\nEach pair of lines becomes a line of four grays: the top 400 lines as 576 x 200 in 640 mode.",
        "mpnt320": "MacPaint as 320 mode black & white: MacPaint documents (Mac file type PNTG) are 576 x 720 dots, black and white, packed with PackBits. A MacBinary header is skipped.\nThe top left 320 x 200 dots are loaded in 320 mode, black on white.",
        "mpntmono": "MacPaint as monochrome image: MacPaint documents (Mac file type PNTG) are 576 x 720 dots, black and white, packed with PackBits. A MacBinary header is skipped.\nThe whole page becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "macsm": "ScreenMaker: the startup screen of early Macintoshes, made with ScreenMaker: a plain 512 x 342 bitmap in black and white, 21888 bytes. A MacBinary header is skipped.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "pict": "QuickDraw picture (PICT): the Macintosh’s picture format, version 1 or 2, with or without the 512 bytes a Mac file starts with.\nReads the pictures in it: bitmaps and pixel maps, packed or not, of 1 to 32 bits a pixel; the lines, shapes and text it may also draw are left out.",
        "bmp": "Windows or OS/2 bitmap (.BMP): the plain picture file of Windows PCs.\nRead by macOS, every kind it knows. It becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "gem": "GEM IMG: the bitmap pictures (.IMG) of Digital Research’s GEM and of Ventura Publisher, with 1 to 8 bit planes, run coded.\nShown in grays, 0 as white and the highest value as black: a true color picture, which the Remap dialog then turns into a screen image.",
        "pcx": "PC Paintbrush (.PCX, .PCC): ZSoft’s PC paint program format, run coded: 2 to 16 colors in bit planes, 256 colors with a palette at the end, or 24-bit color. PCC files are clippings.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "lbm": "IFF: the Amiga’s standard picture file (FORM ILBM), also used by DeluxePaint on the PC (FORM PBM, .LBM): 1 to 8 bit planes, Extra HalfBrite, HAM and 24-bit, packed or not, found anywhere in the file.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "fliaway": "FliAway frame: one frame of an Autodesk Animator animation (.FLI, PC), saved by the FliAway utility: 256 colors and the 320 x 200 frame, packed with PackBytes or not.\nIt becomes a 320 x 200 true color picture, which the Remap dialog then turns into a screen image.",
        "sun": "Sun Rasterfile: the bitmap format of Sun workstations (.RAS): 1, 8, 24 or 32 bits a pixel, with or without a color map, plain or run coded.\nIt becomes a true color picture of its own size (up to 4096 x 4096), which the Remap dialog then turns into a screen image.",
        "sgi": "SGI image: the picture format of Silicon Graphics workstations (.SGI, .RGB, .BW): gray or RGB (alpha is ignored), 8 or 16 bits a sample, plain or run coded.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "pnm": "PBM, PGM, PPM: the portable bitmap, graymap and pixmap files of the Unix PBMPLUS (Netpbm) tools: black & white, gray or color, as text (P1 to P3) or binary (P4 to P6).\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "cpc0": "Amstrad CPC mode 0 screen (.SCR): the CPC’s 16K of screen memory, with or without its AMSDOS header or packed by OCP Art Studio, as mode 0: 160 x 200 in 16 colors.\nIt becomes a screen image in the colors of the .PAL file beside it, or the CPC’s start-up colors.",
        "cpc1": "Amstrad CPC mode 1 screen (.SCR): the CPC’s 16K of screen memory, with or without its AMSDOS header or packed by OCP Art Studio, as mode 1: 320 x 200 in 4 colors (a .PAL file beside it can say another mode).\nIt becomes a screen image in the colors of the .PAL file, or the CPC’s start-up colors.",
        "cpc2": "Amstrad CPC mode 2 screen (.SCR): the CPC’s 16K of screen memory, with or without its AMSDOS header or packed by OCP Art Studio, as mode 2: 640 x 200 in 2 colors.\nIt becomes a 640 mode screen image.",
        "mic": "MicroPainter (.MIC): Atari 8-bit pictures, 160 x 192 in 4 colors (7680 bytes, and the 4 color registers if the file has them; else grays).\nIt becomes a screen image in close to the Atari’s colors.",
        "gr8": "Atari Graphics 8 screen (.GR8): 320 x 192 in 2 colors, 7680 bytes.\nIt becomes a black and white screen image.",
        "gr9": "Atari Graphics 9 screen (.GR9): 80 x 192 in 16 grays, 7680 bytes.\nIt becomes a screen image in 16 grays, its dots four times as wide.",
        "msx2": "MSX Screen 2 (.SC2): the MSX’s 256 x 192 graphics screen saved with BSAVE, a color pair for each line of each 8 x 8 cell.\nIt becomes a screen image in the MSX’s 16 colors.",
        "msx5": "MSX2 Screen 5 (.SC5, .GE5): 256 x 212 in 16 colors from a palette of 512, saved with BSAVE (the palette from the file if it holds it, else the MSX2’s own).\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "msx7": "MSX2 Screen 7 (.SC7): 512 x 212 in 16 colors from a palette of 512, saved with BSAVE; its dots are half as wide as tall.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "msx8": "MSX2 Screen 8 (.SC8): 256 x 212 in 256 colors (3 bits of green, 3 of red, 2 of blue), saved with BSAVE.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "zx": "ZX Spectrum screen (.SCR): the Sinclair ZX Spectrum’s screen, 6912 bytes: 256 x 192 dots and a color pair for each 8 x 8 cell (a 6144-byte file: the dots alone, black on white).\nIt becomes a screen image in the Spectrum’s 15 colors.",
        "jpeg": "JPEG (JFIF): the usual format for photographs (.JPG), compressed with some loss.\nRead by macOS, every kind it knows. It becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "gif": "GIF: CompuServe’s Graphics Interchange Format (87a and 89a), up to 256 colors.\nRead by macOS, every kind it knows. It becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "png": "PNG (Portable Network Graphics): the lossless picture format of today’s computers.\nRead by macOS, every kind it knows. It becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "rle": "RLE: CompuServe’s run-length coded pictures (.RLE), 256 x 192 or 128 x 96 dots in black and white, kept as plain text that may start anywhere in the file, so a terminal’s capture buffer will do.\nLoaded in 320 mode.",
        "ipi": "IPI image: a format of the Image Processing Institute (University of Southern California): three files named alike but ending .R, .G and .B, squares of 8-bit samples, 256 or 512 a side. Pick any one, the other two are read with it.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "qrt": "QRT raw image: the output of QRT, the Quick Ray Tracer: width and height, then each line’s number and its rows of red, green and blue samples, 8 bits each.\nIt becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "tiff": "TIFF: the Tagged Image File Format of desktop publishing and scanners.\nRead by macOS, every kind it knows. It becomes a true color picture, which the Remap dialog then turns into a screen image.",
        "tga": "Truevision Targa (.TGA): pictures from paint and video programs, usually ProDOS type $06 (BIN).\nReads color-mapped, true color and gray pictures, run-length coded or not, of 8, 15, 16, 24 or 32 bits a pixel; an alpha channel is left out.",
        "any": "Anything macOS can open: any picture file macOS reads, such as HEIC, WebP or PDF.\nRead by macOS, every kind it knows. It becomes a true color picture, which the Remap dialog then turns into a screen image.",
    ]

    public static let save: [String: String] = [
        "c00": "PaintWorks: the format of the first PaintWorks Plus, ProDOS type $C0 (PNT), aux type $0000: color table 0, empty painting patterns, then the lines packed with PackBytes.\nFor 320 mode pictures only. Lines using other color tables change color.",
        "c01": "PackBytes screen: the whole 32768-byte screen, SCBs and color tables included, packed with the toolbox routine PackBytes, ProDOS type $C0 (PNT), aux type $0001.\nSmaller than a $C1 screen with nothing lost, but few programs read it.",
        "c02": "Apple Preferred: the standard IIgs picture format, ProDOS type $C0 (PNT), aux type $0002, read by nearly all IIgs graphics programs: the best choice in most cases.\nA MAIN block with the 16 color tables and all 200 lines, 320 or 640 pixels wide, each packed with PackBytes and keeping its SCB.",
        "c1": "$C1 screen: the whole Super Hi-Res screen as it is in memory, 32768 bytes (pixels, SCBs and 16 color tables), ProDOS type $C1 (PIC), aux type $0000.\nEvery IIgs graphics program reads it, though it is not packed. Always a whole screen.",
        "icon": "Finder icon, new file: an icon file, ProDOS type $CA (ICN), with one icon for any file: the picture as the large icon and a reduced copy as the small one.\nThe picture must be 640 mode, at most 160 x 50 (80 x 25 is usual), and should use the standard colors, as the Finder does.",
        "iconadd": "Finder icon, add to a file: the same icon, added after the last one in an icon file you choose, so several icons can share one file. Same limits: 640 mode, at most 160 x 50.\nLeave the system disk’s own icon files alone: new system software replaces them.",
        "ricon": "Icon resource, new file: a new file (ProDOS type $06, BIN) whose resource fork holds the picture as an rIcon ($8001) resource, ID 1, for use in programs.\n320 or 640 mode, at most a quarter of the screen (8000 bytes of pixels).",
        "riconadd": "Icon resource, add to a file: the picture as one more rIcon ($8001) resource, with the lowest free ID, added to a resource file you choose, such as a program of your own.\n320 or 640 mode, at most a quarter of the screen (8000 bytes of pixels).",
        "hex": "Hex data, for programmers: a text file (ProDOS type $04, TXT) with an assembler line for each picture line, its pixel bytes in hexadecimal, as in dc h’00 11 22’.\nOnly the picture’s own size, two pixels a byte in 320 mode and four in 640 mode, without SCBs or colors.",
        "gif": "GIF: a GIF file for other computers, written by macOS.\nWritten as it looks, with square pixels: lines twice and 320 mode pixels twice across (a full screen gives 640 x 400). Each pixel keeps the color it shows, whatever its palette.",
        "png": "PNG: a PNG file for today’s computers, written by macOS.\nWritten as it looks, with square pixels: lines twice and 320 mode pixels twice across (a full screen gives 640 x 400). Each pixel keeps the color it shows, whatever its palette.",
        "tiff": "TIFF: a TIFF file for desktop publishing and other programs, written by macOS.\nWritten as it looks, with square pixels: lines twice and 320 mode pixels twice across (a full screen gives 640 x 400). Each pixel keeps the color it shows, whatever its palette.",
        "bmp": "BMP: a Windows bitmap for today’s computers, written by macOS.\nWritten as it looks, with square pixels: lines twice and 320 mode pixels twice across (a full screen gives 640 x 400). Each pixel keeps the color it shows, whatever its palette.",
        "hgr": "HiRes color: the Apple II high resolution screen, ProDOS type $06 (BIN), aux type $2000, 8192 bytes: 280 x 192 dots in black, white, violet, green, blue and orange.\nThe picture is fitted to the Apple II screen and dithered, a pair of dots at a time; each byte of 7 dots shows blue and orange or violet and green, whichever its part of the picture is closer to. Apple II save options choose the dithering (error diffusion, pattern or none) and whether the picture fills the screen or keeps its proportions.",
        "hgrbw": "HiRes black & white: the Apple II high resolution screen, ProDOS type $06 (BIN), aux type $2000, 8192 bytes: 280 x 192 dots.\nThe picture is fitted to the Apple II screen and dithered; a black & white picture keeps its dots where they fit. Apple II save options choose the dithering (error diffusion, pattern or none) and whether the picture fills the screen or keeps its proportions.",
        "dhr": "Double HiRes color: the double high resolution screen of the Apple IIe, IIc and IIgs, ProDOS type $06 (BIN), aux type $2000, 16384 bytes, the auxiliary memory half first: 140 x 192 pixels in 16 colors.\nThe picture is fitted to the Apple II screen and dithered; a picture in the Apple II colors keeps them. Apple II save options choose the dithering (error diffusion, pattern or none) and whether the picture fills the screen or keeps its proportions.",
        "dhrbw": "Double HiRes black & white: the Apple II double high resolution screen, ProDOS type $06 (BIN), aux type $2000, 16384 bytes, the auxiliary half first: 560 x 192 dots.\nThe picture is fitted to the Apple II screen and dithered. Apple II save options choose the dithering (error diffusion, pattern or none) and whether the picture fills the screen or keeps its proportions.",
        "lores": "LoRes: the Apple II low resolution screen, ProDOS type $06 (BIN), aux type $0400, 1024 bytes (the text page): 40 x 48 blocks in 16 colors.\nThe picture is fitted to the Apple II screen and dithered; a picture in the Apple II colors keeps them. Apple II save options choose the dithering (error diffusion, pattern or none) and whether the picture fills the screen or keeps its proportions.",
        "dlores": "Double LoRes: the low resolution screen of the Apple IIe, IIc and IIgs with 80 columns, ProDOS type $06 (BIN), aux type $0400, 2048 bytes, the auxiliary memory half first: 80 x 48 blocks in 16 colors.\nThe picture is fitted to the Apple II screen and dithered; a picture in the Apple II colors keeps them. Apple II save options choose the dithering (error diffusion, pattern or none) and whether the picture fills the screen or keeps its proportions.",
        "hgrp": "HiRes color, packed: the Apple II high resolution screen packed with PackBytes, ProDOS type $08 (FOT), aux type $4000, as Apple’s File Type Note has it.\nThe picture is made as for HiRes color (280 x 192, dithered in its six colors), then packed.",
        "hgrbwp": "HiRes black & white, packed: the Apple II high resolution screen packed with PackBytes, ProDOS type $08 (FOT), aux type $4000.\nThe picture is made as for HiRes black & white, then packed.",
        "dhrp": "Double HiRes color, packed: the double high resolution screen packed with PackBytes, the auxiliary memory half first, ProDOS type $08 (FOT), aux type $4001, as Apple’s File Type Note has it.\nThe picture is made as for Double HiRes color (140 x 192 in 16 colors), then packed.",
        "dhrbwp": "Double HiRes black & white, packed: the double high resolution screen packed with PackBytes, the auxiliary half first, ProDOS type $08 (FOT), aux type $4001.\nThe picture is made as for Double HiRes black & white, then packed.",
    ]
}
